import java.util.*;

class Solution {
  public int largestPathValue(String colors, int[][] edges) {
    int n = colors.length();
    List<Integer>[] g = new List[n];
    int[] indeg = new int[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      indeg[e[1]]++;
    }
    int[][] dp = new int[n][26];
    ArrayDeque<Integer> q = new ArrayDeque<>();
    for (int i = 0; i < n; i++) if (indeg[i] == 0) q.add(i);
    int seen = 0, answer = 0;
    while (!q.isEmpty()) {
      int u = q.remove();
      seen++;
      int c = colors.charAt(u) - 'a';
      dp[u][c]++;
      for (int v : g[u]) {
        for (int j = 0; j < 26; j++) dp[v][j] = Math.max(dp[v][j], dp[u][j]);
        if (--indeg[v] == 0) q.add(v);
      }
    }
    if (seen < n) return -1;
    for (int[] row : dp) for (int x : row) answer = Math.max(answer, x);
    return answer;
  }
}
